DROP TABLE IF EXISTS `mmf_rate_history`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `mmf_rate_history` (
  `id` int NOT NULL AUTO_INCREMENT,
  `mmfFundId` int NOT NULL,
  `fundName` varchar(200) NOT NULL,
  `grossYield` decimal(8,4) DEFAULT NULL,
  `ear` decimal(8,4) DEFAULT NULL,
  `managementFee` decimal(6,4) DEFAULT NULL,
  `effectiveAt` bigint NOT NULL,
  `source` varchar(300) DEFAULT NULL,
  `sourceUrl` varchar(500) DEFAULT NULL,
  `researchUpdateId` int DEFAULT NULL,
  `approvedBy` varchar(200) DEFAULT NULL,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  KEY `mmf_rate_history_fund_idx` (`mmfFundId`,`effectiveAt`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin AUTO_INCREMENT=450001;
/*!40101 SET character_set_client = @saved_cs_client */;

