--
-- Table structure for table `opportunities`
--

DROP TABLE IF EXISTS `opportunities`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `opportunities` (
  `id` int NOT NULL AUTO_INCREMENT,
  `ref` varchar(64) NOT NULL,
  `name` varchar(200) NOT NULL,
  `assetClass` varchar(32) NOT NULL,
  `issuer` varchar(200) DEFAULT NULL,
  `currency` varchar(8) NOT NULL DEFAULT 'KES',
  `market` varchar(64) DEFAULT NULL,
  `yieldPct` decimal(7,4) DEFAULT NULL,
  `yieldKind` varchar(48) DEFAULT NULL,
  `lastPrice` decimal(16,4) DEFAULT NULL,
  `trailingReturnPct` decimal(8,4) DEFAULT NULL,
  `tenorYears` decimal(6,2) DEFAULT NULL,
  `maturityDate` date DEFAULT NULL,
  `expenseRatioPct` decimal(6,4) DEFAULT NULL,
  `liquidity` varchar(32) DEFAULT NULL,
  `factNote` text DEFAULT NULL,
  `dataSource` varchar(200) DEFAULT NULL,
  `dataAsOf` timestamp NULL DEFAULT NULL,
  `unverified` tinyint(1) NOT NULL DEFAULT '1',
  `active` tinyint(1) NOT NULL DEFAULT '1',
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `fieldProvenance` json DEFAULT NULL,
  `verificationState` varchar(24) NOT NULL DEFAULT 'scraped_unverified',
  `aiSourceImageKeys` json DEFAULT NULL,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  UNIQUE KEY `ref` (`ref`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin AUTO_INCREMENT=1770001;
/*!40101 SET character_set_client = @saved_cs_client */;

