--
-- Table structure for table `research_findings`
--

DROP TABLE IF EXISTS `research_findings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `research_findings` (
  `id` int NOT NULL AUTO_INCREMENT,
  `taskId` int NOT NULL,
  `instrumentName` varchar(200) NOT NULL,
  `issuer` varchar(200) DEFAULT NULL,
  `assetClass` varchar(32) DEFAULT NULL,
  `targetCatalogue` enum('mmf','bank','cbk','market_asset','macro') NOT NULL,
  `currency` varchar(8) NOT NULL DEFAULT 'KES',
  `extractedFields` json DEFAULT NULL,
  `sourceLabel` varchar(300) DEFAULT NULL,
  `sourceUrl` varchar(500) DEFAULT NULL,
  `finding_source_kind` enum('url','text','pdf','image') DEFAULT NULL,
  `sourceAsOf` bigint DEFAULT NULL,
  `checkedAt` bigint DEFAULT NULL,
  `confidence` enum('low','medium','high') NOT NULL DEFAULT 'medium',
  `missingFields` json DEFAULT NULL,
  `warnings` json DEFAULT NULL,
  `rawExcerpt` text DEFAULT NULL,
  `status` enum('new','drafted','dismissed','superseded') NOT NULL DEFAULT 'new',
  `draftedUpdateId` int DEFAULT NULL,
  `reviewedBy` varchar(200) DEFAULT NULL,
  `reviewedAt` bigint DEFAULT NULL,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `thread_id` int DEFAULT NULL,
  `superseded_by_id` int DEFAULT NULL,
  `supersedes_id` int DEFAULT NULL,
  `corrected_by` varchar(200) DEFAULT NULL,
  `corrected_at` bigint DEFAULT NULL,
  `correction_reason` text DEFAULT NULL,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */,
  KEY `idx_research_findings_task` (`taskId`),
  KEY `idx_research_findings_status` (`status`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin AUTO_INCREMENT=870001;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `research_findings`
--

LOCK TABLES `research_findings` WRITE;
/*!40000 ALTER TABLE `research_findings` DISABLE KEYS */;
