--
-- Table structure for table `research_tasks`
--

DROP TABLE IF EXISTS `research_tasks`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `research_tasks` (
  `id` int NOT NULL AUTO_INCREMENT,
  `portfolioId` int DEFAULT NULL,
  `createdByOpenId` varchar(200) NOT NULL,
  `createdByName` varchar(200) DEFAULT NULL,
  `prompt` text NOT NULL,
  `scope` enum('mmf','bank','cbk','market_asset','macro','any') NOT NULL DEFAULT 'any',
  `status` enum('running','queued','done','error','needs_source_fix','failed') NOT NULL DEFAULT 'running',
  `stage` enum('queued','reading_source','asking_ai','extracting','done','needs_source_fix','failed') NOT NULL DEFAULT 'queued',
  `kind` enum('ask','review') NOT NULL DEFAULT 'ask',
  `review_catalogue` enum('mmf','bank','cbk','market_asset') DEFAULT NULL,
  `source_kind` enum('url','text','pdf','image') DEFAULT NULL,
  `source_ref` text DEFAULT NULL,
  `source_label` varchar(200) DEFAULT NULL,
  `allow_unsourced` tinyint(1) NOT NULL DEFAULT '0',
  `source_status` json DEFAULT NULL,
  `answerSummary` text DEFAULT NULL,
  `aiModel` varchar(64) DEFAULT NULL,
  `findingCount` int NOT NULL DEFAULT '0',
  `error` varchar(400) DEFAULT NULL,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `completedAt` bigint DEFAULT NULL,
  `thread_id` int DEFAULT NULL,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin AUTO_INCREMENT=1020001;
/*!40101 SET character_set_client = @saved_cs_client */;

--
