INSERT INTO `research_tasks` VALUES (1,NULL,'6cD924EKpryXuYpd78USGP','James Otieno','What Treasury bills are on offer this week?','cbk','done','done','ask',NULL,NULL,NULL,NULL,0,NULL,'The Central Bank of Kenya is offering 91-day, 182-day, and 364-day Treasury bills for auction this week, with an auction date of July 2nd, 2026, and a value date of July 6th, 2026. The previous average interest rates for these bills were 8.8275% for the 91-day, 8.8438% for the 182-day, and 8.9932% for the 364-day. I could not confirm the current offer amounts for these Treasury bills.','gemini-2.5-flash',3,NULL,'2026-07-02 00:43:38',1782953022492,NULL),(30001,NULL,'6cD924EKpryXuYpd78USGP','James Otieno','what T Bonds were offered this week?','any','done','done','ask',NULL,NULL,NULL,NULL,0,NULL,'The Central Bank of Kenya offered two Treasury Bonds this week: an infrastructure bond (IFB1/2024/16) and a new 10-year Treasury Bond (FXD1/2024/10). The infrastructure bond has a tenor of 16 years and was offered for 25 billion KES, with bidding closing on February 14, 2024, and results to be announced on February 19, 2024. The new 10-year bond was offered for 30 billion KES, with bidding also closing on February 14, 2024, and results announced on February 19, 2024. Specific coupon rates for these bonds were not immediately available in the offering circulars but would be determined by market bids.','gemini-2.5-flash',2,NULL,'2026-07-02 17:22:48',1783012974049,NULL),(60001,NULL,'6cD924EKpryXuYpd78USGP','James Otieno','check online for the t bonds offered this week by cbk','any','done','done','ask',NULL,NULL,NULL,NULL,0,NULL,'The Central Bank of Kenya (CBK) did not offer any new Treasury Bonds this week. The only government securities offered are Treasury Bills, with an auction scheduled for 2024-07-04.','gemini-2.5-flash',2,NULL,'2026-07-02 18:14:25',1783016068081,1),(60002,NULL,'6cD924EKpryXuYpd78USGP','James Otieno','but google ai mode says and lists those cbk t bonds offered this week. can you check again','any','done','done','ask',NULL,NULL,NULL,NULL,0,NULL,'My previous information regarding the absence of new Treasury Bond offers from the Central Bank of Kenya (CBK) this week appears to be correct. I have re-checked the official CBK website for auction announcements and confirmed that only Treasury Bills are scheduled for auction on 2024-07-04. There are no new Treasury Bond offerings listed for this week. It is possible that the \'Google AI mode\' you referred to might be referencing past auctions or general information about T-bonds rather than current weekly offerings.','gemini-2.5-flash',2,NULL,'2026-07-02 18:15:31',1783016134783,1),(90001,NULL,'6cD924EKpryXuYpd78USGP','James Otieno','I have pasted the AI Mode response for you to see for those t bonds offered according to Gemini. Please confirm','any','done','done','ask',NULL,NULL,NULL,NULL,0,NULL,'','gemini-2.5-flash',0,NULL,'2026-07-02 18:17:01',1783016229580,1),(120001,NULL,'sample-admin','Admin Person','Catalogue review: MMF Market — Test fact sheet','mmf','done','done','ask',NULL,NULL,NULL,NULL,0,NULL,'From the fact sheet, ZZ Review-Only MMF 1783018289753 quotes an EAR of 16.10%.','test-model',1,NULL,'2026-07-02 18:51:31',1783018291726,30001),(120002,NULL,'sample-admin','Admin Person','Catalogue review: CBK Securities Reference — CBK weekly auction results','cbk','done','done','ask',NULL,NULL,NULL,NULL,0,NULL,'Latest weekly T-bill auction: 91, 182 and 364-day results below.','test-model',3,NULL,'2026-07-02 18:51:32',1783018292369,30002),(120003,NULL,'sample-admin','Admin Person','Catalogue review: Bank Product Catalogue — KCB rate sheet','bank','done','done','ask',NULL,NULL,NULL,NULL,0,NULL,'The rate sheet quotes a 12-month fixed deposit at 13.5% (indicative, gross of WHT).','test-model',1,NULL,'2026-07-02 18:51:32',1783018292939,30003),(150001,NULL,'sample-admin','Admin Person','Catalogue review: MMF Market — Test fact sheet','mmf','done','done','ask',NULL,NULL,NULL,NULL,0,NULL,'From the fa