DROP TABLE IF EXISTS `research_threads`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `research_threads` (
  `id` int NOT NULL AUTO_INCREMENT,
  `portfolioId` int DEFAULT NULL,
  `createdByOpenId` varchar(200) NOT NULL,
  `createdByName` varchar(200) DEFAULT NULL,
  `title` varchar(300) NOT NULL,
  `scope` enum('mmf','bank','cbk','market_asset','macro','any') NOT NULL DEFAULT 'any',
  `archived` tinyint(1) NOT NULL DEFAULT '0',
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin AUTO_INCREMENT=780001;
/*!40101 SET character_set_client = @saved_cs_client */;

