DROP TABLE IF EXISTS `research_updates`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `research_updates` (
  `id` int NOT NULL AUTO_INCREMENT,
  `target` enum('mmf','bank','opportunity') NOT NULL,
  `targetRef` varchar(64) DEFAULT NULL,
  `changeKind` enum('create','edit') NOT NULL DEFAULT 'create',
  `name` varchar(200) NOT NULL,
  `assetClass` varchar(32) NOT NULL,
  `issuer` varchar(200) DEFAULT NULL,
  `currency` varchar(8) NOT NULL DEFAULT 'KES',
  `figures` json DEFAULT NULL,
  `source` varchar(300) NOT NULL,
  `sourceUrl` varchar(500) DEFAULT NULL,
  `asOf` bigint DEFAULT NULL,
  `origin` enum('ai','manual','scrape') NOT NULL DEFAULT 'manual',
  `aiModel` varchar(64) DEFAULT NULL,
  `sourceKey` varchar(64) DEFAULT NULL,
  `status` enum('pending','approved','rejected','superseded','conflict') NOT NULL DEFAULT 'pending',
  `reviewNote` text DEFAULT NULL,
  `reviewedBy` varchar(200) DEFAULT NULL,
  `reviewedAt` bigint DEFAULT NULL,
  `createdAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updatedAt` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `findingId` int DEFAULT NULL,
  `field` varchar(48) DEFAULT NULL,
  `oldValue` varchar(200) DEFAULT NULL,
  `managerValue` varchar(200) DEFAULT NULL,
  `finding_id` int DEFAULT NULL,
  `old_value` text DEFAULT NULL,
  `manager_value` text DEFAULT NULL,
  PRIMARY KEY (`id`) /*T![clustered_index] CLUSTERED */
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin AUTO_INCREMENT=900001;
/*!40101 SET character_set_client = @saved_cs_client */;

